inline const uint8_t* frankFullSprite(FrankState state) {
  switch (state) {
    case FRANK_DEAD:      return frank_dead_200x200;
    case FRANK_CLOSED:    return frank_closed_200x200;
    case FRANK_HALF_OPEN: return frank_half_open_200x200;
    case FRANK_AWAKE:     return frank_awake_200x200;
    case FRANK_BLINK:     return frank_blink_200x200;
    case FRANK_HAPPY:     return frank_happy_200x200;
    case FRANK_RECORDING: return frank_recording_200x200;
    case FRANK_ERROR:     return frank_error_200x200;
    default:              return frank_awake_200x200;
  }
}

inline const uint8_t* frankFaceSprite(FrankState state) {
  switch (state) {
    case FRANK_DEAD:      return frank_face_dead_96x52;
    case FRANK_CLOSED:    return frank_face_closed_96x52;
    case FRANK_HALF_OPEN: return frank_face_half_open_96x52;
    case FRANK_AWAKE:     return frank_face_awake_96x52;
    case FRANK_BLINK:     return frank_face_blink_96x52;
    case FRANK_HAPPY:     return frank_face_happy_96x52;
    case FRANK_RECORDING: return frank_face_recording_96x52;
    case FRANK_ERROR:     return frank_face_error_96x52;
    default:              return frank_face_awake_96x52;
  }
}
